import type * as D3 from 'd3';

type NodeRequire = typeof require & {
  resolve: (id: string) => string;
};

function load_d3_umd_for_jest(): typeof D3 {
  const nodeRequire = require as NodeRequire;
  const path = nodeRequire('path') as typeof import('path');
  const fs = nodeRequire('fs') as typeof import('fs');
  const vm = nodeRequire('vm') as typeof import('vm');
  const d3Entry = nodeRequire.resolve('d3');
  const d3Root = path.resolve(path.dirname(d3Entry), '..');
  const d3UmdBundle = path.join(d3Root, 'dist', 'd3.min.js');
  const d3Exports = {};

  vm.runInNewContext(
    fs.readFileSync(d3UmdBundle, 'utf8'),
    {
      exports: d3Exports,
      module: {exports: d3Exports}
    },
    {filename: d3UmdBundle}
  );

  return d3Exports as typeof D3;
}

function load_d3(): typeof D3 {
  if (process.env.NODE_ENV === 'test') {
    return load_d3_umd_for_jest();
  }

  return require('d3') as typeof D3;
}

